const stores = [
  { id: 's1', from: 'old', to: 'young' },   // recorded
  { id: 's2', from: 'young', to: 'young' },  // skipped
  { id: 's3', from: 'old', to: 'old' },      // skipped
  { id: 's4', from: 'old', to: 'young' },    // recorded
  { id: 's5', from: 'young', to: 'old' },    // skipped
];

const rememberedSet = [];
for (const s of stores) {
  if (s.from === 'old' && s.to === 'young') rememberedSet.push(s.id);
}
console.log('remembered=' + rememberedSet.join(',') + ' count=' + rememberedSet.length);

